INSERT INTO "Mcq" ("id","question","optionA","optionB","optionC","optionD","correctAnswer","hint","explanation","sourceType","sourceRef","difficulty","lectureId","createdAt") VALUES('6bbed16e-6602-42f1-a453-3e4e74627dd6','A patient presents with a thyroid swelling that is slowly growing. Which of the following is mentioned in the lecture as a possible diagnosis?','Anaplastic carcinoma','Papillary carcinoma','Thyroiditis','Hemorrhage','B',NULL,'The lecture states that slow-growing thyroid swellings can be seen with papillary and follicular carcinoma, while rapidly growing swellings suggest anaplastic carcinoma.','ai','','Medium','43bc6f2b-e9cd-4965-862f-4b0155d0b2dd','2026-08-22T23:55:00.493Z');
