INSERT INTO "Mcq" ("id","question","optionA","optionB","optionC","optionD","correctAnswer","hint","explanation","sourceType","sourceRef","difficulty","lectureId","createdAt") VALUES('6dc8872a-2a61-474d-90ba-7c0f3f42e295','1. A virus contains a single-stranded RNA genome that is directly translated by host ribosomes immediately after entering the cell. Which type of genome does it have?','Negative-sense ssRNA','Positive-sense ssRNA','Double-stranded RNA','Positive-sense ssDNA','B',NULL,'(+ssRNA) can act directly as mRNA. * So, after entering the cell, it can be immediately translated by host ribosomes. * Examples: Picornavirus, Flavivirus, Coronavirus.','ai','','Medium','7c119fbe-a92a-46d9-901d-b91a04b7ed8e','2026-08-22T21:26:14.711Z');
