INSERT INTO "Mcq" ("id","question","optionA","optionB","optionC","optionD","correctAnswer","hint","explanation","sourceType","sourceRef","difficulty","lectureId","createdAt") VALUES('b0e0c377-021a-4c51-8226-829a5179f506','Which pathogen is the most important bacterial cause of healthcare-associated gastroenteritis?','E. coli','Clostridium difficile','Pseudomonas aeruginosa','Staphylococcus aureus','B',NULL,'It is associated with diarrhea and pseudomembranous colitis, especially after antibiotic use such as cephalosporins and clindamycin','ai','','Medium','47a02f87-5adf-40e3-a9a3-f63fb89020be','2026-08-22T22:53:36.655Z');
