INSERT INTO "Mcq" ("id","question","optionA","optionB","optionC","optionD","correctAnswer","hint","explanation","sourceType","sourceRef","difficulty","lectureId","createdAt") VALUES('b5fafb94-e04b-4fe9-a64c-4229c54259b7','Which mechanism is responsible for antigenic shift in Influenza A?','Point mutations in HA/NA','Reassortment of RNA segments','Integration into host DNA','Reverse transcription','B',NULL,'Because influenza has a segmented RNA genome, segments can reassort and produce a new subtype, potentially causing pandemics','ai','','Medium','e191691b-7d6a-41e5-bc76-12084dc15ca4','2026-08-22T21:41:00.416Z');
