INSERT INTO "Mcq" ("id","question","optionA","optionB","optionC","optionD","correctAnswer","hint","explanation","sourceType","sourceRef","difficulty","lectureId","createdAt") VALUES('b6effa1e-0847-4752-9f43-788159b64e9e','Which of the following best describes PubMed?','A paid database containing only full-text articles','A free resource providing access to MEDLINE citations and abstracts','A database limited to nursing articles','A database containing only systematic reviews','B',NULL,NULL,'ai','','Medium','d379977e-cd22-4b4d-84ac-3055142addc5','2026-08-23T01:02:33.809Z');
INSERT INTO "Mcq" ("id","question","optionA","optionB","optionC","optionD","correctAnswer","hint","explanation","sourceType","sourceRef","difficulty","lectureId","createdAt") VALUES('b88869fe-5661-47df-bd8b-c2f849cfbca8','Which of the following viruses requires an RNA-dependent RNA polymerase inside the viral particle for successful infection?','Picornavirus','Flavivirus','Coronavirus','Orthomyxovirus','A',NULL,'* Negative-sense RNA viruses cannot be directly translated, so they must carry RNA-dependent RNA polymerase (RdRp) inside the virion. * Picornavirus is +ssRNA, so technically it does NOT need to carry RdRp inside the virion. * Therefore, Q2 as written is actually flawed. The best answer would be Orthomyxovirus (Influenza) because it is a −ssRNA virus and carries RdRp.','ai','','Medium','7c119fbe-a92a-46d9-901d-b91a04b7ed8e','2026-08-22T21:27:25.023Z');
INSERT INTO "Mcq" ("id","question","optionA","optionB","optionC","optionD","correctAnswer","hint","explanation","sourceType","sourceRef","difficulty","lectureId","createdAt") VALUES('b98b28ae-952b-4a75-8d97-2e2ec8e07152','Which molecular technique is used to detect viral DNA or RNA?','Gram stain','PCR','Culture only','Latex agglutination','B',NULL,NULL,'ai','','Medium','ff140cbc-a1bd-4f0c-8291-b8a217abcce2','2026-08-23T09:23:05.186Z');
