INSERT INTO "Mcq" ("id","question","optionA","optionB","optionC","optionD","correctAnswer","hint","explanation","sourceType","sourceRef","difficulty","lectureId","createdAt") VALUES('cdec93d6-e71a-48e4-a7cc-fee9240ef34c','Which is the most active form of vitamin D?','Cholecalciferol','Ergocalciferol','Calcitriol','Calcidiol','C',NULL,NULL,'ai','','Medium','4d2c7167-a10d-4b77-97e5-e2785f4c2675','2026-08-22T22:19:05.213Z');
INSERT INTO "Mcq" ("id","question","optionA","optionB","optionC","optionD","correctAnswer","hint","explanation","sourceType","sourceRef","difficulty","lectureId","createdAt") VALUES('d03fd314-3d0f-4f7e-88f8-01eb3c934ff9','Which type of variable can assume any value within a specified interval without gaps or interruptions','Discrete variable','Continuous variable','Qualitative variable','Nominal variable','B',NULL,'Examples given in the lecture include weight, height, and mid-arm circumference','ai','','Medium','caeb4b50-a3d9-4e0f-b886-b16e850d7609','2026-08-22T23:36:42.470Z');
INSERT INTO "Mcq" ("id","question","optionA","optionB","optionC","optionD","correctAnswer","hint","explanation","sourceType","sourceRef","difficulty","lectureId","createdAt") VALUES('d122b88b-bfea-4040-8d90-1fff9cb53843','Which of the following is a qualitative variable?','Age','Weight','Height','Diseased vs. healthy','D',NULL,'Qualitative variables cannot be measured in the usual sense but can be categorized.','ai','','Medium','caeb4b50-a3d9-4e0f-b886-b16e850d7609','2026-08-22T23:35:54.404Z');
INSERT INTO "Mcq" ("id","question","optionA","optionB","optionC","optionD","correctAnswer","hint","explanation","sourceType","sourceRef","difficulty","lectureId","createdAt") VALUES('d1e2acc9-b511-4d08-9bc4-a97b7ddb4022','Which stain is used to demonstrate the capsule of fungi?','Gram stain','Ziehl-Neelsen stain','India ink stain','Safranin','C',NULL,NULL,'ai','','Medium','45dcc4c1-3d21-4619-846a-51f04e055f69','2026-08-23T09:31:32.116Z');
INSERT INTO "Mcq" ("id","question","optionA","optionB","optionC","optionD","correctAnswer","hint","explanation","sourceType","sourceRef","difficulty","lectureId","createdAt") VALUES('db1c1cd4-bd9c-43f8-926c-9463d4cb697b','Which statement is correct when performing a basic PubMed search?','Always use quotation marks','Always add the operator AND between concepts','Be specific and enter concepts as phrases','Use as few terms as possible','C',NULL,NULL,'ai','','Medium','d379977e-cd22-4b4d-84ac-3055142addc5','2026-08-23T01:03:18.720Z');
INSERT INTO "Mcq" ("id","question","optionA","optionB","optionC","optionD","correctAnswer","hint","explanation","sourceType","sourceRef","difficulty","lectureId","createdAt") VALUES('dd2280d7-636e-4369-aa7a-0c32cf400030','Which of the following is the correct sequence of the PBAR method?','Problem → Background → Analysis → Recommendations','Problem → Analysis → Background → Recommendations','Background → Problem → Recommendations → Analysis','Problem → Recommendations → Background → Analysis','A',NULL,'The purpose of PBAR is to organize case presentations and trigger decision-making.','ai','','Medium','bf625781-0100-477d-b61e-c66edb956a2d','2026-08-22T23:48:10.410Z');
INSERT INTO "Mcq" ("id","question","optionA","optionB","optionC","optionD","correctAnswer","hint","explanation","sourceType","sourceRef","difficulty","lectureId","createdAt") VALUES('dd635a3a-cb69-45e1-85cd-9e2cf7a16003','Which of the following is the most common major site of healthcare-associated infection according to the lecture?','Pneumonia','Urinary tract infection','Bloodstream infection','Surgical site infection','C',NULL,'The three major sites are bloodstream infections (28%), pneumonia (21%), and UTI (15%).','ai','','Medium','47a02f87-5adf-40e3-a9a3-f63fb89020be','2026-08-22T22:52:45.541Z');
INSERT INTO "Mcq" ("id","question","optionA","optionB","optionC","optionD","correctAnswer","hint","explanation","sourceType","sourceRef","difficulty","lectureId","createdAt") VALUES('de0335cc-d5d9-41d0-a7d3-c1a5a058b5a0','Which hormone increases water permeability of the collecting ducts?','Aldosterone','ADH','Renin','Angiotensin I','B',NULL,NULL,'ai','','Medium','891fa890-fa10-463f-b232-eeced22c17ad','2026-08-23T08:41:48.106Z');
INSERT INTO "Mcq" ("id","question","optionA","optionB","optionC","optionD","correctAnswer","hint","explanation","sourceType","sourceRef","difficulty","lectureId","createdAt") VALUES('e3be1dd9-5e49-455d-9f94-163aadaa20dd','What is the first step in an outbreak investigation?','Define a case','Confirm the diagnosis','Determine the existence of an outbreak','Communicate findings','C',NULL,NULL,'ai','','Medium','9a521a28-d005-47e7-8203-d5be9a0d36a7','2026-08-23T09:18:49.686Z');
INSERT INTO "Mcq" ("id","question","optionA","optionB","optionC","optionD","correctAnswer","hint","explanation","sourceType","sourceRef","difficulty","lectureId","createdAt") VALUES('e9870989-4626-42cb-ba0a-d867376e4a76','Which of the following is included in the study of angio-edema in this lecture?','Only its clinical features','Only its causes','Its types, pathogenesis, clinical features, investigations and management','Only its treatment','C',NULL,NULL,'ai','','Medium','7224208b-3477-4c53-9388-a9dba2d98938','2026-08-23T00:59:14.290Z');
INSERT INTO "Mcq" ("id","question","optionA","optionB","optionC","optionD","correctAnswer","hint","explanation","sourceType","sourceRef","difficulty","lectureId","createdAt") VALUES('ebfff85f-8f42-4610-bcbc-cb1c9d2dd845','Which of the following is a feature of secondary thyrotoxicosis according to the lecture?','Exophthalmos is always prominent','Tremor is the predominant feature','Palpitations and arrhythmias','Thyroid swelling and toxic features appear simultaneously','C',NULL,'The lecture describes secondary thyrotoxicosis as mainly having CVS manifestations, including palpitation, ectopic beats, arrhythmia, dyspnea, chest pain, ankle edema and congestive cardiac failure','ai','','Medium','43bc6f2b-e9cd-4965-862f-4b0155d0b2dd','2026-08-22T23:55:50.048Z');
INSERT INTO "Mcq" ("id","question","optionA","optionB","optionC","optionD","correctAnswer","hint","explanation","sourceType","sourceRef","difficulty","lectureId","createdAt") VALUES('f396c76a-837a-4a4c-ae0c-c3cd050f7510','Which of the following is the correct definition of Maternal Death?','Death of a woman only during labor','Death of a woman from any cause during pregnancy, including accidental causes','Death of a woman during pregnancy or within 42 days of termination, from causes related to or aggravated by pregnancy, excluding accidental/incidental causes','Death occurring only within 28 days after delivery','C',NULL,NULL,'ai','','Medium','064ecddd-5e56-4767-8c03-ad8d1fc7f839','2026-08-23T00:33:43.772Z');
INSERT INTO "Mcq" ("id","question","optionA","optionB","optionC","optionD","correctAnswer","hint","explanation","sourceType","sourceRef","difficulty","lectureId","createdAt") VALUES('f713db7a-c854-438c-a370-56f57fe52863','How many stool specimens usually suffice for diagnosis of intestinal parasitic diseases?','One','Two','Three','Five','C',NULL,NULL,'ai','','Medium','f037b65a-ed17-4628-948f-f348788dd05e','2026-08-23T09:15:02.890Z');
INSERT INTO "Mcq" ("id","question","optionA","optionB","optionC","optionD","correctAnswer","hint","explanation","sourceType","sourceRef","difficulty","lectureId","createdAt") VALUES('f8b5900f-070f-489a-a3f2-a668a5e6f304','Which of the following is characteristic of Mycetoma?','Acute infection acquired by inhalation','Chronic infection with multiple sinuses and discharge containing grains','Infection limited to the oral cavity','Viral infection causing vesicular lesions','B',NULL,'Mycetoma is a chronic, progressively destructive infection acquired by traumatic inoculation into subcutaneous tissue, commonly affecting the foot.','ai','','Medium','02365fd2-ed48-451e-b5e2-a5abea48fa12','2026-08-22T22:48:19.312Z');
INSERT INTO "Mcq" ("id","question","optionA","optionB","optionC","optionD","correctAnswer","hint","explanation","sourceType","sourceRef","difficulty","lectureId","createdAt") VALUES('f95c824c-5f93-41be-88df-ac44d07f8819','Which of the following is NOT part of the anatomy of a scientific article?','Abstract','Introduction','Material and methods','Patient consent form','D',NULL,NULL,'ai','','Medium','f926cb4a-e328-46c2-97b0-fe2f2d5e0722','2026-08-23T01:07:48.568Z');
INSERT INTO "Mcq" ("id","question","optionA","optionB","optionC","optionD","correctAnswer","hint","explanation","sourceType","sourceRef","difficulty","lectureId","createdAt") VALUES('fa9112df-d9c2-4d47-9bb4-ea33c7d6f9d4','Which of the following is part of the current definition of FUO?','Fever for ≥1 week','Fever ≥38.3°C on at least two occasions','Any fever in an immunocompromised patient','Diagnosis established after initial examination','B',NULL,NULL,'ai','','Medium','a7300bd6-7c50-4378-9ec8-f267fc85e6ee','2026-08-23T09:26:20.965Z');
INSERT INTO "Mcq" ("id","question","optionA","optionB","optionC","optionD","correctAnswer","hint","explanation","sourceType","sourceRef","difficulty","lectureId","createdAt") VALUES('fe122a58-d733-44b7-861c-6268f5502bf7','Which of the following is a characteristic of innate immunity?','Immunologic memory','Antigenic specificity','No memory','Ability to distinguish self from foreign','C',NULL,NULL,'ai','','Medium','8faed0ec-286a-4da4-b3f7-7d069ed891f2','2026-08-23T00:42:27.157Z');
INSERT INTO "Mcq" ("id","question","optionA","optionB","optionC","optionD","correctAnswer","hint","explanation","sourceType","sourceRef","difficulty","lectureId","createdAt") VALUES('ff0464a9-acd8-4d1f-b753-8ee63dc632c3','What is the best definition of critical appraisal?','Reading the abstract of a research paper','The process of carefully and systematically examining research to judge its trustworthiness, value and relevance','Checking whether an article is published in a famous journal','Comparing two research articles','B',NULL,NULL,'ai','','Medium','f926cb4a-e328-46c2-97b0-fe2f2d5e0722','2026-08-23T01:06:55.768Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('02aca28d-a6bc-4132-a575-c22d21af4e55','What are the three qSOFA criteria?','SBP ≤100 mmHg, RR ≥22/min, and GCS <15','bc63a899-0468-4948-9e5c-55e4c3748ab6','2026-08-23T09:06:19.037Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('07daea03-bb84-40ca-b2b0-768b738419a2','What should you do at the beginning of taking a patient’s history?','Introduction → Permission → Comfort → Privacy → Rapport → Open questions.','d313afd4-10bd-49f7-92d0-30a8be9dfe4b','2026-08-23T00:01:24.677Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('0843b7d0-9852-442e-bcb6-3bb9fcf3f1a9','What are the 3 major healthcare-associated infections and their percentages?',replace('1. 🩸 Bloodstream infection → 28%\n2. 🫁 Pneumonia → 21%\n3. 🩺 Urinary tract infection → 15%','\n',char(10)),'47a02f87-5adf-40e3-a9a3-f63fb89020be','2026-08-22T22:53:58.710Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('0ec4c469-c30f-4385-a01e-e2afdb7cc391','What is the purpose of the streak plate method?','To obtain isolated colonies and produce a pure culture.','067342ff-5a7c-4d95-a531-0848a8ed3b77','2026-08-23T09:00:49.842Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('11ed029b-1714-4be4-b78a-c5f87b52f9cb','What are the 4 types of Dietary Reference Intake (DRI)?',replace('EAR → meets needs of 50%\n* RDA → meets needs of 97–98%\n* AI → used when RDA is not established\n* UL → highest average daily intake unlikely to cause toxicity in 97% of healthy individuals.','\n',char(10)),'da05512e-ab1b-49a5-a983-ad535092061b','2026-08-22T23:08:54.913Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('13a2ac53-db12-466d-948a-5ed4860e466d','What is the difference between antigenic drift and antigenic shift?',replace('Antigenic drift → minor changes due to mutations.\n* Antigenic shift → major changes due to reassortment of RNA segments.\n* Influenza A can undergo both; B and C undergo drift but not shift.','\n',char(10)),'faa0337f-63e2-432a-9c47-70fe9008b4f1','2026-08-22T22:00:40.941Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('13c19503-a14d-4f29-9b4a-40ad5d25cef8','What are the main topics to know about Anaphylaxis?','Anaphylaxis → Clinical features + Causes + DDx + Emergency management','7224208b-3477-4c53-9388-a9dba2d98938','2026-08-23T00:59:36.324Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('15ab8834-e39b-49e6-88f2-87c7982e562c','What are the three main components of total energy requirement?','BMR + Physical activity + Thermic effect of food.','83b4328f-b607-42b2-ad4d-9d9b2501516b','2026-08-23T08:19:35.828Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('18f77160-16d9-43b4-9b37-96f2e416c722','Which trace elements are covered in this lecture, and what is the key deficiency feature of each',replace('Copper\n\nAnemia + neutropenia\n\nIodine\n\nGoiter\n\nSelenium\n\nKeshan cardiomyopathy\n\nManganese\n\nScaly dermatitis\n\nMolybdenum\n\nNeurological + ocular problems\n\nChromium\n\nHyperglycemia + impaired glucose tolerance','\n',char(10)),'dfa13e18-2ffa-4529-bd12-5bd77a4da359','2026-08-22T23:27:36.575Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('19f56657-1613-4802-b6e4-25e774744734','What are the four major categories of FUO causes?','Infections, noninfectious inflammatory diseases, malignancies, and miscellaneous causes.','a7300bd6-7c50-4378-9ec8-f267fc85e6ee','2026-08-23T09:26:57.957Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('1b9b7aac-d024-412e-acde-117d60341e4e','What are the important indications for surgical treatment of hydatid cyst?',replace('Surgery is indicated particularly for:\n\n* Large liver cysts with multiple daughter cysts\n* Superficially located liver cysts with risk of rupture\n* Cysts communicating with the biliary tree\n* Cysts causing pressure on vital structures\n* Infected cysts\n* Cysts located in the lung, brain, kidney, eye or bone','\n',char(10)),'2861ae97-9a5e-4901-8ff5-de5ae94c3ed0','2026-08-22T22:40:56.597Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('1bea2446-3617-4fb6-b1c1-d22f2af42923','What are the main laboratory diagnostic steps for mycoses?','Specimen collection, direct microscopy, culture, biochemical tests, serology/molecular tests, and biopsy with histopathology.','45dcc4c1-3d21-4619-846a-51f04e055f69','2026-08-23T09:31:55.729Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('1f3ef79b-4d78-4caf-875d-2e7d28374381','What is the recommended blood product ratio in massive bleeding?','Massive hemorrhage → 1:1:1 + permissive hypotension (BP up to ~90 mmHg).','b941856a-0af9-4870-ad3f-08facfb70581','2026-08-22T23:21:53.896Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('20cf1b17-5f21-4a50-bec1-0756c27938d3','What are the main clinical features and complications of P. falciparum malaria?','Symptoms: fever, chills, sweating, anorexia, nausea, headache, muscle/joint pain, cough and diarrhea, with possible anemia and splenomegaly.','258f81d5-a28d-4daa-a360-c3ab8d56ff8e','2026-08-22T22:35:05.442Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('26ad1496-d090-4bee-ad37-5b51acc3e5a9','What are the important neurological manifestations of vitamin B12 deficiency?','B12 = Blood + Brain + Spinal cord.','594639a2-d263-40c2-8132-1af26914c571','2026-08-22T23:03:37.564Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('270e7c49-4ea5-4c95-adb9-37a8730fa313','What are the main clinical features of iodine deficiency?','Iodine deficiency → Goiter + severe deficiency → Hypothyroidism + fetal cretinism.','dfa13e18-2ffa-4529-bd12-5bd77a4da359','2026-08-22T23:27:12.111Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('2c0dc20f-e13d-4286-9579-10a3ed6934c3','What is the difference between antigenic drift and antigenic shift?',replace('Drift → minor HA/NA mutations\n* Shift → reassortment → new subtype\n* Shift is associated with pandemics','\n',char(10)),'e191691b-7d6a-41e5-bc76-12084dc15ca4','2026-08-22T21:41:33.844Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('2f5f8117-4683-4340-ba56-0305c162e4c3','What are the three general approaches for laboratory diagnosis of viral infections?','Direct demonstration of the virus/components, virus isolation, and detection of specific antibodies.','ff140cbc-a1bd-4f0c-8291-b8a217abcce2','2026-08-23T09:23:23.618Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('337e3ee8-5dfd-46e2-bf8a-e28bbff255a1','What is the standard framework for taking a history?',replace('Patient details\n2. Chief Complaint + Duration\n3. History of Present Illness (HPI)\n4. Review of Systems (ROS)\n5. Past Medical History (PMH)\n6. Past Surgical History (PSH)\n7. Family History (FH)\n8. Personal & Social History (SH)\n9. Occupational History (OH)\n10. Drug History + Allergies (DH)','\n',char(10)),'d313afd4-10bd-49f7-92d0-30a8be9dfe4b','2026-08-23T00:01:03.609Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('33a1fdc1-6d22-474e-b44b-d3b4b8f75b96','What are the two main parts of General Stool Examination (GSE)?','Macroscopic examination and microscopic examination.','f037b65a-ed17-4628-948f-f348788dd05e','2026-08-23T09:15:52.020Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('34ea3dee-efc4-4efe-9ae4-cda5fb85c028','What is the life cycle of E. histolytica?','Ingestion of cyst → excystation in ileum → trophozoites → multiplication by binary fission in large intestine → some remain in lumen, some invade intestinal mucosa → bloodstream → extraintestinal sites → cyst formation.','698726eb-108f-416c-85ab-f3a4004fc69c','2026-08-22T22:22:47.239Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('36cf1095-aacb-4490-b57f-fe0da1c21bba','How is S. aureus identified in the laboratory?',replace('Gram-positive cocci in grape-like clusters\n* Catalase positive\n* Coagulase positive\n* On blood agar → usually β-hemolytic\n* On Mannitol Salt Agar → mannitol fermentation → yellow discoloration','\n',char(10)),'09154094-7505-4872-8fea-6891783b2bbc','2026-08-22T22:07:58.985Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('3c0d7db9-3404-455d-bfe3-30c861d7f240','What is the main function of vitamin K?','It is essential for prothrombin formation and normal blood clotting.','4d2c7167-a10d-4b77-97e5-e2785f4c2675','2026-08-22T22:19:52.731Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('3c5f8182-4903-4bb0-bfbe-ac76f35b80b1','What is a pure culture?','A single type of microorganism growing alone in a protected environment.','b976ad93-b83e-4b09-9d1f-3db8ac482213','2026-08-23T09:11:20.535Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('3f09e2d8-3894-4569-a389-ce8d10b173a9','How do you calculate the number and width of class intervals?','Sturge’s Rule → K = 1 + 3.322 log n.','99a41fdc-b30e-4999-afce-88f98a4565fc','2026-08-22T23:43:35.978Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('4308c006-e0aa-4a31-b9c6-903db641aa20','What are the important characteristics of Nocardia spp.?',replace('Gram-positive\n* Branching filaments\n* Aerobic\n* Non-motile\n* Found in the environment, not normal human flora\n* Stained with acid-fast (A-F) stain in tissues\n* Can produce sulfur granules, similar to Actinomyces\n* Common species include:\n    * N. nova\n    * N. farcinica\n    * N. brasiliensis\n    * N. asteroides','\n',char(10)),'02365fd2-ed48-451e-b5e2-a5abea48fa12','2026-08-22T22:48:45.204Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('4803a803-101c-4b2e-8a09-bfe44f093ed2','What is the major atherogenic lipoprotein?','LDL cholesterol.','19bd8c78-7b46-4700-90ee-731cc3b19af7','2026-08-22T22:09:01.656Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('4d5986ef-44a4-41b7-b437-ea6de5816ce6','What important topics should be covered in the management of bronchial asthma?','Triggers + Status asthmaticus + Management.','4e3f1f0b-c05f-4cfd-90ce-a29372a7bda5','2026-08-23T00:53:32.918Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('4d7d965a-fe71-4461-8794-5e49991d11c1','What are the important clinical features of amoebic liver abscess?',replace('Usually affects the right hepatic lobe\n* May occur without diarrhea\n* Fever, chills, rigors and sweating are common\n* Tender hepatomegaly\n* Right upper quadrant pain\n* May cause right shoulder pain\n* Can rupture through the diaphragm into the lung\n* Aspirated pus classically has an anchovy-sauce / chocolate-brown appearance.','\n',char(10)),'e6881ece-05a7-4335-99e0-1ac3db391daf','2026-08-22T22:29:04.768Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('50c456da-c56f-4006-9b85-ae44270b1b32','What are the Three Delays Model responsible for maternal deaths?','D1 = Decide → D2 = Deliver/reach → D3 = Receive care','064ecddd-5e56-4767-8c03-ad8d1fc7f839','2026-08-23T00:34:54.741Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('512da50f-aaaf-4ff0-8e99-067827b32770','What is the difference between E. histolytica and E. dispar?','They cannot be reliably distinguished by cyst morphology; molecular techniques can distinguish them.','698726eb-108f-416c-85ab-f3a4004fc69c','2026-08-22T22:23:14.673Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('51ae6d7b-c982-4b9a-8020-1933567b93f3','What is MeSH and why is it useful?','MeSH = controlled vocabulary → better/more consistent article retrieval.','d379977e-cd22-4b4d-84ac-3055142addc5','2026-08-23T01:03:45.856Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('51b347e8-4892-4fc7-a5a8-b8603e71a528','What are the main reagents of Gram staining?','Crystal violet, Gram’s iodine, alcohol/acetone, and safranin.','067342ff-5a7c-4d95-a531-0848a8ed3b77','2026-08-23T09:00:59.114Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('53740c46-962a-40fe-a3a4-405dea9fbf6f','What are the four levels of measurement?','Nominal → Ordinal → Interval → Ratio','99a41fdc-b30e-4999-afce-88f98a4565fc','2026-08-22T23:43:13.589Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('5656570b-0072-49c9-975d-129c266f8b57','What lipid pattern is commonly seen in diabetes mellitus?','High triglycerides with low HDL cholesterol.','c35d8f13-b583-45db-bd7e-3ada6f25dca9','2026-08-23T08:25:32.422Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('5b1f343f-171a-438c-a81f-0fc2cfd7ebc3','What are the four fat-soluble vitamins?','Vitamins A, D, E, and K.','4d2c7167-a10d-4b77-97e5-e2785f4c2675','2026-08-22T22:19:42.281Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('5d1549f7-d118-4bab-9c88-451597c1e4d1','What are typical clinical clues for familial hypercholesterolemia?','Very high LDL from a young age, premature family history of CHD/MI, and tendon xanthomas or thickened Achilles tendons.','c35d8f13-b583-45db-bd7e-3ada6f25dca9','2026-08-23T08:25:21.021Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('5de0b2f0-8825-4fa6-b6c0-4e44c1d18b25','What are the important investigations for Allergy?','Gold standard = Skin prick test','52eae338-1ea5-4e26-a58e-9370b03b9cac','2026-08-23T00:47:57.800Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('5ef516fb-3aac-453a-b139-9b1191b997ca','What is the usual adult maintenance fluid requirement?','Approximately 30 mL/kg/24 hours.','891fa890-fa10-463f-b232-eeced22c17ad','2026-08-23T08:42:16.420Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('63afa825-00c0-4f12-93d9-2c98750d2c70','What are the functions of HA and NA?',replace('HA: binds the virus to receptors on susceptible host cells.\n* NA: facilitates release of virions and degrades respiratory mucus.','\n',char(10)),'faa0337f-63e2-432a-9c47-70fe9008b4f1','2026-08-22T22:01:04.939Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('63cb495b-2a65-46ad-bb87-4189c7129b6f','What happens when ECF tonicity increases?','Water shifts from intracellular to extracellular fluid, causing cell shrinkage.','772dd4b2-872d-49cd-af7c-00bdc7797781','2026-08-23T08:48:48.433Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('67fc0f10-b1bc-4646-aa02-117908790c19','What are common transport media for microbiological specimens?','Amies transport medium and Stuart’s transport medium.','8c447550-d4fc-43a9-9888-607e4e942e28','2026-08-23T08:55:14.244Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('6aec9cff-336c-4af7-a227-a6b3f0dc81a1','What are the key features of Influenza A?',replace('Enveloped, negative-sense RNA\n* Has HA & NA spikes\n* Has mammalian and avian reservoirs\n* Undergoes both antigenic drift and shift\n* Causes pandemics.','\n',char(10)),'e191691b-7d6a-41e5-bc76-12084dc15ca4','2026-08-22T21:41:56.390Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('6ccb703f-9406-49b2-a721-9d11c15ab895','What are the functions of HA and NA, and what is the difference between antigenic drift and shift?',replace('HA (Hemagglutinin): binds viral particles to receptors on susceptible cells.\n* NA (Neuraminidase): facilitates release of new virions and helps degrade respiratory mucus.\n* Antigenic drift: minor changes → mutations\n* Antigenic shift: major changes → reassortment of RNA segments; occurs in Influenza A.','\n',char(10)),'7c119fbe-a92a-46d9-901d-b91a04b7ed8e','2026-08-22T21:29:39.250Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('6d56d29d-1403-4594-8fb5-e27c52213366','What are the 4 important types of Angioedema?',replace('Allergic + Idiopathic → Histamine\nHereditary + ACE-I → Bradykinin','\n',char(10)),'52eae338-1ea5-4e26-a58e-9370b03b9cac','2026-08-23T00:48:19.591Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('716886fc-c0ef-483a-a0e8-9cee57de5efa','What is the difference between osmolarity and osmolality?',replace('OsmO-LARity → Liter\nOsmO-LALity → kg of water','\n',char(10)),'fa5a8d0d-09a0-4618-a10e-fdcb1e0a0406','2026-08-22T23:16:44.284Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('75a887d1-a926-4d56-a157-bef4ceda7676','What are the important features of Rubella?','Mild illness + low-grade fever + posterior auricular/suboccipital lymphadenopathy + rash. In pregnancy, congenital rubella can cause hearing loss, cataracts, and PDA.','e3c26245-b7be-4a83-bac4-3ba655f28a8a','2026-08-22T21:54:45.905Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('75cb4c98-40c7-4102-babf-e4f112651ee8','What should you know about Angio-edema?','Types → Pathogenesis → Features → Investigations → Management','7224208b-3477-4c53-9388-a9dba2d98938','2026-08-23T00:59:56.495Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('7678711b-e266-4acf-b03e-937ae0a7c40d','How is amoebiasis treated?',replace('1. Tissue/invasive infection:\n• Metronidazole 800 mg TID for 5-10 days\n• Or tinidazole/ornidazole\n2. Eradication of luminal cysts:\nAfter treatment, give a luminal agent such as:\n• Diloxanide furoate\n• Paromomycin\n3. Large/threatening liver abscess:\n→ Aspiration may be required, especially if the response to treatment is not prompt or rupture is threatened.','\n',char(10)),'e6881ece-05a7-4335-99e0-1ac3db391daf','2026-08-22T22:30:00.851Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('77a5308b-1c97-4e0c-aa3b-0faca928e3e0','What color do Gram-negative bacteria appear after Gram staining?','Red, because they take up safranin.','b976ad93-b83e-4b09-9d1f-3db8ac482213','2026-08-23T09:11:28.767Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('77d75cd8-cccc-439f-bd3e-981b3c6e1f3f','What are the key structural and genomic features of Influenza virus?',replace('Enveloped virus with helical nucleocapsid\n* ssRNA, negative-sense\n* Segmented genome: 8 segments in Influenza A & B, 7 in C\n* Carries RNA-dependent RNA polymerase\n* Replication/transcription occurs in the nucleus.','\n',char(10)),'7c119fbe-a92a-46d9-901d-b91a04b7ed8e','2026-08-22T21:29:14.342Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('7efc3403-f59d-4a21-9f4f-57850f255aa0','What should be assessed in the Results section?','Results → Consistency + Presentation + P value + R value','f926cb4a-e328-46c2-97b0-fe2f2d5e0722','2026-08-23T01:08:33.846Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('7ff6503f-356c-4712-829d-2b5776561290','What are the classic clinical features of measles?','Fever + conjunctivitis + coryza + cough + Koplik spots, followed by a red blotchy rash that starts on the face and becomes generalized.','e3c26245-b7be-4a83-bac4-3ba655f28a8a','2026-08-22T21:54:26.288Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('83fae6c7-2977-474b-8564-ac8bb6480908','What is oxidized LDL (oxLDL)?','LDL modified by oxidation that promotes inflammation, foam-cell formation, and atherosclerosis.','386a169d-f5da-41e8-854e-6973ff6d469d','2026-08-22T21:58:46.947Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('867b54d0-e7db-4b4d-aeb1-a66b86421472','What are the main features of hepatic hydatid cyst?',replace('Most common site of involvement.\n* Common symptoms:\n    * Abdominal pain\n    * Dyspepsia\n    * Vomiting\n* Most frequent sign → Hepatomegaly / palpable mass\n* Local complications include:\n    * Exophytic extension\n    * Transdiaphragmatic extension\n    * Biliary involvement\n    * Abdominal wall involvement\n    * Portal vein involvement','\n',char(10)),'2861ae97-9a5e-4901-8ff5-de5ae94c3ed0','2026-08-22T22:40:36.876Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('8a6fdde6-ce06-464a-9941-40cee0af5d3d','What happens to a cell in isotonic, hypotonic, and hypertonic solutions?',replace('Isotonic → cell neither swells nor shrinks\n* Hypotonic → water enters → cell swells\n* Hypertonic → water leaves → cell shrinks','\n',char(10)),'fa5a8d0d-09a0-4618-a10e-fdcb1e0a0406','2026-08-22T23:16:18.304Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('8bf81545-04e1-47af-b00c-a98298de7d13','What is Mycetoma and what are its characteristic features?','Mycetoma is a non-contagious, chronic, progressively destructive inflammatory infection caused by either bacteria or fungi following traumatic inoculation into subcutaneous tissue.','02365fd2-ed48-451e-b5e2-a5abea48fa12','2026-08-22T22:49:03.507Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('8d1887a1-7228-46d7-8beb-130f8803cd84','What are the main objectives related to the pathogenesis of bronchial asthma?','Asthma → Atopy → Allergen → Immunopathogenesis','4e3f1f0b-c05f-4cfd-90ce-a29372a7bda5','2026-08-23T00:53:14.314Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('8e0f6189-1d90-40b1-84c8-471a1d4ecb6f','What imaging is recommended after initial CXR and abdominal ultrasound in FUO?','CT of the chest, abdomen, and pelvis; PET/CT may be used as advanced imaging.','a7300bd6-7c50-4378-9ec8-f267fc85e6ee','2026-08-23T09:27:08.801Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('8ef19f9c-f5bc-4995-8c3b-e86e38f68ba2','What is the difference between Frequency, Relative Frequency, and Cumulative Frequency?','Example from the lecture: for fasting glucose 63–65, frequency = 5, relative frequency = 50%, cumulative frequency = 7.','caeb4b50-a3d9-4e0f-b886-b16e850d7609','2026-08-22T23:37:31.126Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('911d78f4-2007-4795-bfd7-68b46eaac9d2','What are the guidelines for dealing with a patient’s family?','Acknowledge → Listen → Privacy → Contact person → Document → Short visits → Don’t examine in front of relatives.','28853e3f-fe21-4632-9ea4-81ca327ed9d2','2026-08-23T00:06:45.503Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('93a42e33-6087-4dc5-a226-1711d1266a8b','What are the main Search Tools and search considerations in PubMed?',replace('MeSH = terminology\nClinical Queries = clinically relevant literature\nLimits = date + language + age + publication type','\n',char(10)),'d379977e-cd22-4b4d-84ac-3055142addc5','2026-08-23T01:04:07.823Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('94459ae1-6bcd-4a5f-87ac-eca273475c4c','What is mycology?','The science that deals with the study of fungi.','45dcc4c1-3d21-4619-846a-51f04e055f69','2026-08-23T09:31:47.520Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('96bc2b50-80b0-4ed2-8a19-53fed6564e13','What is dyslipidemia?','Abnormal lipid levels in the blood.','19bd8c78-7b46-4700-90ee-731cc3b19af7','2026-08-22T22:08:50.708Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('9a013c06-a65b-40fe-b8ec-6abad585cc13','What are the main serological markers of hepatitis B?','HBsAg, anti-HBs, total anti-HBc, HBeAg, and anti-HBe.','ff140cbc-a1bd-4f0c-8291-b8a217abcce2','2026-08-23T09:23:31.707Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('9c799dfa-1550-499f-8aa8-d91bfb8180f2','What is Public Health?','Public Health = Prevention + Health promotion + Prolonging life + Organized efforts of society','294f21d4-d795-473c-9cf4-f489a24c55ce','2026-08-23T00:18:52.437Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('9d6067c7-b7ea-4f82-bb37-6731bba41d02','What are the three components of valid informed consent?','Disclosure + Capacity + Voluntariness = Valid informed consent','28853e3f-fe21-4632-9ea4-81ca327ed9d2','2026-08-23T00:06:28.492Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('a11630c8-9fb6-4f38-bd59-cd47a37a13f2','What is the major atherogenic lipoprotein?','LDL cholesterol','36beb4c8-2b3e-4837-a7d8-93ad4ad7b9ed','2026-08-22T22:14:20.843Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('a19da1c6-4f40-4891-943e-613144ec3b06','What are the main steps of surgical scrubbing after preparation?','Nails → Sponge → Fingertips → Hands → Forearms → Other side → Rinse D→P → Faucet with elbows/knees.','01e23f89-5e55-463b-bca7-2c9c268a3925','2026-08-23T00:12:21.918Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('a41c5b33-1e16-4a4d-a943-2597a0a3786e','What is the Iceberg Phenomenon of Disease?',replace('🧊 Above water: visible/symptomatic disease → what the physician sees.\n* 🌊 Under water: pre-symptomatic/subclinical disease → what the physician does not see','\n',char(10)),'294f21d4-d795-473c-9cf4-f489a24c55ce','2026-08-23T00:19:18.213Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('a4932571-3f70-4d35-9c70-d69bcb30822e','What are the 3 stages of learning a skill?','The lecture illustrates these stages on page 3, progressing with practice time.','bf625781-0100-477d-b61e-c66edb956a2d','2026-08-22T23:49:30.896Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('a53ec236-7e17-48ce-8ec3-da232f70a1e3','What are the steps before starting surgical scrubbing?','No jewelry + short nails + mask/cap + bare arms above elbow.','01e23f89-5e55-463b-bca7-2c9c268a3925','2026-08-23T00:11:55.864Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('a87c30e8-f812-4ca8-9729-4711c6992617','What is an outbreak?','The occurrence of a health-related event clearly in excess of normal expectancy.','9a521a28-d005-47e7-8203-d5be9a0d36a7','2026-08-23T09:19:29.328Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('a965e917-0f41-4505-95b0-49f79e8336f8','What are the six classes of nutrients?',replace('Carbs + Protein + Fat = energy-yielding\nVitamins + Minerals + Water = do not provide energy','\n',char(10)),'da05512e-ab1b-49a5-a983-ad535092061b','2026-08-22T23:08:27.120Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('acae2df7-6983-4493-a0a8-7d14aa78576c','What is the normal AMDR for carbohydrates?','45–65% of total energy intake.','83b4328f-b607-42b2-ad4d-9d9b2501516b','2026-08-23T08:19:49.579Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('af5862ee-999e-4453-9be4-ed4989f2c8a3','What are the different types of cases in infectious disease epidemiology?',replace('Index case → the first case identified\n* Primary case → the case that brings the infection into a population\n* Secondary case → infected by a primary case\n* Tertiary case → infected by a secondary case','\n',char(10)),'02cbd85c-5648-4e90-b60d-53e80ddacb8c','2026-08-22T22:17:02.993Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('afbad588-2e65-4d55-a9ed-d25a0f09e3d6','How is dehydration classified by percentage body-weight loss?','Mild <5%, moderate 5–10%, severe 10–15%.','891fa890-fa10-463f-b232-eeced22c17ad','2026-08-23T08:42:08.057Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('b112cd37-5151-439e-b8e3-b92efd7703c7','What are the formulas for the main measures of fertility?',replace('CBR → total population\nGFR → women of child-bearing age\nASFR → women of a specific age.','\n',char(10)),'064ecddd-5e56-4767-8c03-ad8d1fc7f839','2026-08-23T00:35:27.737Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('baef34f3-a6a5-4f11-8158-c753fa6f5611','What are the differences between primary and secondary thyrotoxicosis?',replace('Primary = CNS + Eye\nSecondary = CVS','\n',char(10)),'43bc6f2b-e9cd-4965-862f-4b0155d0b2dd','2026-08-22T23:56:38.060Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('bda1ae70-8d01-4d85-8d5b-6d8e6c84c235','What are the main components of PBAR?','PBAR = Problem → Background → Analysis → Recommendations.','bf625781-0100-477d-b61e-c66edb956a2d','2026-08-22T23:49:49.453Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('bde1209f-b372-4c70-b1f1-b30c1c1a0375','What should be assessed in the Methodology section during critical appraisal?','Methodology = Design + Sampling + Sample size + Data collection + Statistics + Ethics','f926cb4a-e328-46c2-97b0-fe2f2d5e0722','2026-08-23T01:08:13.454Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('bed06c87-4dbb-48c5-81d4-7000e5a423e6','What are the main instrument-associated healthcare infections?',replace('Endotracheal tube → sinusitis, tracheitis, pneumonia\n* Intravascular catheter → phlebitis, line infection / bloodstream infection\n* Foley catheter → urinary tract infection','\n',char(10)),'47a02f87-5adf-40e3-a9a3-f63fb89020be','2026-08-22T22:54:22.088Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('c2ad7e04-b435-418e-8be7-e4056e6e6f78','What are the main principles of sepsis management?','Recognition, supportive care, source control, antibiotics, and adjunctive therapy.','bc63a899-0468-4948-9e5c-55e4c3748ab6','2026-08-23T09:06:28.330Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('c4942919-c920-4575-8070-8fada892170e','What important features should be asked about when taking the history of a neck swelling?','Rapid growth + pain/pressure symptoms = think carefully about malignancy and complications.','43bc6f2b-e9cd-4965-862f-4b0155d0b2dd','2026-08-22T23:56:15.218Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('c5cae9c5-962c-42d0-9dc1-f30021eec53d','What is the difference between Population and Sample?',replace('All children enrolled in a school = Population\nWeights of only some of those children = Sample.','\n',char(10)),'caeb4b50-a3d9-4e0f-b886-b16e850d7609','2026-08-22T23:37:08.525Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('c7321247-40ff-47b7-ace7-e670a71c7c5b','What are the three main approaches to control an epidemic?','Control the source, interrupt transmission, and control or modify the host response.','9a521a28-d005-47e7-8203-d5be9a0d36a7','2026-08-23T09:19:40.709Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('c8673794-29db-47c8-bce0-3b61c3b6d9d6','What major abnormalities are present in metabolic syndrome?','Central obesity, hypertension, abnormal glucose metabolism, high triglycerides, and low HDL.','1556ee77-6af3-42fb-bffe-d5f13535209f','2026-08-23T08:38:43.146Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('cba2b637-d921-4763-b847-96421b0b507b','What are the 5 classes of immunoglobulins and their heavy chains?',replace('GAMDE → G-A-M-D-E\nوالـ heavy chains: γ α μ δ ε','\n',char(10)),'8faed0ec-286a-4da4-b3f7-7d069ed891f2','2026-08-23T00:44:02.027Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('cf8fb473-cf46-4a4d-9c22-c5fba295e4af','What is the main function of HDL?','Reverse cholesterol transport: returning excess cholesterol from peripheral tissues to the liver for excretion.','386a169d-f5da-41e8-854e-6973ff6d469d','2026-08-22T21:58:34.817Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('d23c6790-1f90-4532-8573-249e42a55a1f','What are the 3 Ds of pellagra?','Pellagra = Vitamin B3 (niacin) deficiency','594639a2-d263-40c2-8132-1af26914c571','2026-08-22T23:02:56.226Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('da6ab80a-d188-49c0-bfae-a66e2b5310c1','What are the major exotoxins of S. aureus and what do they cause?',replace('Exfoliatin → Scalded Skin Syndrome (SSS)\n* Enterotoxin → Food poisoning\n* TSST-1 → Toxic Shock Syndrome','\n',char(10)),'09154094-7505-4872-8fea-6891783b2bbc','2026-08-22T22:07:34.589Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('db7ae832-4c01-4fc6-a264-938b43f00d03','What are the main differences between Primary and Secondary immune responses?',replace('Primary = IgM + low affinity + low titer\nSecondary = IgG/IgA + high affinity + high titer','\n',char(10)),'8faed0ec-286a-4da4-b3f7-7d069ed891f2','2026-08-23T00:43:32.151Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('ddb81931-e27b-4197-b0f5-c0802a83dc13','What are the levels of disease occurrence?',replace('Sporadic → occasional cases at irregular intervals\n* Endemic → persistent occurrence at a low–moderate level\n* Hyperendemic → persistently high level of occurrence\n* Epidemic/Outbreak → occurrence clearly above the expected level for a given time\n* Pandemic → epidemic spread across several countries/continents, affecting many people','\n',char(10)),'02cbd85c-5648-4e90-b60d-53e80ddacb8c','2026-08-22T22:17:22.945Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('e0883f1d-5c80-4cf0-b185-9e3a0d0b3059','How is hemorrhage classified according to blood loss?',replace('Class I: ≤15% → usually little physiological change\n* Class II: 15–30% → tachycardia, sweating, vasoconstriction, pale skin, low urine output\n* Class III: 30–40% → vasodilation + hypotension, possible bradycardia/tachycardia\n* Class IV: >40% → cardiovascular collapse and shock; HR >120 bpm, profound hypotension','\n',char(10)),'b941856a-0af9-4870-ad3f-08facfb70581','2026-08-22T23:21:31.603Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('e8afdc9a-28f2-4936-8a3f-9ba418b17146','What is the normal color of stool?','Brown.','f037b65a-ed17-4628-948f-f348788dd05e','2026-08-23T09:15:59.601Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('eb26ee17-c375-448e-a8e5-a41c3758e395','What is the vector and main mode of transmission of malaria?','Vector: 🦟 Infective female Anopheles mosquito','258f81d5-a28d-4daa-a360-c3ab8d56ff8e','2026-08-22T22:35:27.964Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('f4123e21-e00a-406f-a0d6-e5b5f810735a','What are the two major forms of protein-energy malnutrition?','Marasmus and Kwashiorkor.','1556ee77-6af3-42fb-bffe-d5f13535209f','2026-08-23T08:38:32.417Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('f5f84fd8-dd8f-4d94-9819-3d5e8050ce8c','What is the 4-2-1 rule for maintenance fluid?','4 mL/kg/hr for the first 10 kg, 2 mL/kg/hr for the second 10 kg, and 1 mL/kg/hr for each kg above 20 kg.','772dd4b2-872d-49cd-af7c-00bdc7797781','2026-08-23T08:48:37.111Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('fcda6692-57db-4c2a-b247-93b94916ca8c','What is dyslipidemia?','Abnormal lipid levels in the blood.','36beb4c8-2b3e-4837-a7d8-93ad4ad7b9ed','2026-08-22T22:14:11.321Z');
INSERT INTO "Flashcard" ("id","clinicalConcept","explanation","lectureId","createdAt") VALUES('ffdc1be5-2287-4a70-8fe2-4bbe76a5a57c','What should a microbiology specimen container be like?','Sterile, leak-proof, unbreakable, and specimens should never be sent in formalin.','8c447550-d4fc-43a9-9888-607e4e942e28','2026-08-23T08:55:22.627Z');
